/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Poly, Rational, Sym, add, expand, expandFunc, ff, fn, mul, pow, rational, rf } from '../../../src';
import { sympyStr } from '../../sympy-str';

describe("doctests of sympy.functions.combinatorial.factorials", () => {
  it("ff(x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(fn('ff', [x, rational(0)]))).toBe('1');
  });
  it("ff(5, 5)", () => {
    expect(sympyStr(fn('ff', [rational(5), rational(5)]))).toBe('120');
  });
  it("ff(x, 5) == x*(x - 1)*(x - 2)*(x - 3)*(x - 4)", () => {
    const x = new Sym('x');
    expect(sympyStr(mul(x, add(-1, x), add(-4, x), add(-3, x), add(-2, x)).equals(mul(x, add(-1, x), add(-4, x), add(-3, x), add(-2, x))))).toBe('True');
  });
  it("ff(Poly(x**2, x), 2)", () => {
    const x = new Sym('x');
    expect(sympyStr(ff(Poly.from(pow(x, 2), [x], { domain: 'ZZ', pure: false }), rational(2)))).toBe('Poly(x**4 - 2*x**3 + x**2, x, domain=\'ZZ\')');
  });
  it("ff(n, n)", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(fn('ff', [n, n]))).toBe('factorial(n)');
  });
  it("rf(x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(fn('rf', [x, rational(0)]))).toBe('1');
  });
  it("rf(1, 5)", () => {
    expect(sympyStr(fn('rf', [rational(1), rational(5)]))).toBe('120');
  });
  it("rf(x, 5) == x*(1 + x)*(2 + x)*(3 + x)*(4 + x)", () => {
    const x = new Sym('x');
    expect(sympyStr(mul(x, add(1, x), add(2, x), add(3, x), add(4, x)).equals(mul(x, add(1, x), add(2, x), add(3, x), add(4, x))))).toBe('True');
  });
  it("rf(Poly(x**3, x), 2)", () => {
    const x = new Sym('x');
    expect(sympyStr(rf(Poly.from(pow(x, 3), [x], { domain: 'ZZ', pure: false }), rational(2)))).toBe('Poly(x**6 + 3*x**5 + 3*x**4 + x**3, x, domain=\'ZZ\')');
  });
  it("binomial(15, 8)", () => {
    expect(sympyStr(fn('binomial', [rational(15), rational(8)]))).toBe('6435');
  });
  it("binomial(n, -1)", () => {
    const n = new Sym('n', { integer: true, positive: true });
    expect(sympyStr(fn('binomial', [n, rational(-1)]))).toBe('0');
  });
  it("binomial(Rational(5, 4), 3)", () => {
    expect(sympyStr(fn('binomial', [rational(5, 4), rational(3)]))).toBe('-5/128');
  });
  it("binomial(Rational(-5, 4), 3)", () => {
    expect(sympyStr(fn('binomial', [rational(-5, 4), rational(3)]))).toBe('-195/128');
  });
  it("binomial(n, 3)", () => {
    const n = new Sym('n', { integer: true, positive: true });
    expect(sympyStr(fn('binomial', [n, rational(3)]))).toBe('binomial(n, 3)');
  });
  it("binomial(n, 3).expand(func=True)", () => {
    const n = new Sym('n', { positive: true, integer: true });
    expect(sympyStr(expand(fn('binomial', [n, rational(3)]), { func: true }))).toBe('n**3/6 - n**2/2 + n/3');
  });
  it("expand_func(binomial(n, 3))", () => {
    const n = new Sym('n', { positive: true, integer: true });
    expect(sympyStr(expandFunc(fn('binomial', [n, rational(3)])))).toBe('n*(n - 2)*(n - 1)/6');
  });
  it("Mod(binomial(156675, 4433, evaluate=False), 10**5 + 3)", () => {
    expect(sympyStr(Rational.of(28625n))).toBe('28625');
  });
  it("Mod(binomial(10**18, 10**12, evaluate=False), (10**5 + 3)**2)", () => {
    expect(sympyStr(Rational.of(3744312326n))).toBe('3744312326');
  });
  it("factorial(0)", () => {
    expect(sympyStr(fn('factorial', [rational(0)]))).toBe('1');
  });
  it("factorial(7)", () => {
    expect(sympyStr(fn('factorial', [rational(7)]))).toBe('5040');
  });
  it("factorial(-2)", () => {
    expect(sympyStr(fn('factorial', [rational(-2)]))).toBe('zoo');
  });
  it("factorial(n)", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(fn('factorial', [n]))).toBe('factorial(n)');
  });
  it("factorial(2*n)", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(fn('factorial', [mul(2, n)]))).toBe('factorial(2*n)');
  });
  it("factorial(S(1)/2)", () => {
    expect(sympyStr(fn('factorial', [rational(1, 2)]))).toBe('factorial(1/2)');
  });
  it("factorial2(n + 1)", () => {
    const n = new Sym('n');
    expect(sympyStr(fn('factorial2', [add(1, n)]))).toBe('factorial2(n + 1)');
  });
  it("factorial2(5)", () => {
    expect(sympyStr(fn('factorial2', [rational(5)]))).toBe('15');
  });
  it("factorial2(-1)", () => {
    expect(sympyStr(fn('factorial2', [rational(-1)]))).toBe('1');
  });
  it("factorial2(-5)", () => {
    expect(sympyStr(fn('factorial2', [rational(-5)]))).toBe('1/3');
  });
  it("subfactorial(n + 1)", () => {
    const n = new Sym('n');
    expect(sympyStr(fn('subfactorial', [add(1, n)]))).toBe('subfactorial(n + 1)');
  });
  it("subfactorial(5)", () => {
    expect(sympyStr(fn('subfactorial', [rational(5)]))).toBe('44');
  });
  it("n", () => {
    const n = new Sym('n');
    expect(sympyStr(n)).toBe('n');
  });
});
